#include <bits/stdc++.h>
using namespace std;

long long solveOne(int n, long long x, vector<int>& arr) {
    int mn = *min_element(arr.begin(), arr.end());
    int maxA = *max_element(arr.begin(), arr.end());

    // 初始能量小于最小参数，直接返回 x
    if (x < mn) {
        return x;
    }

    // 去重
    vector<int> nums;
    vector<bool> exist(maxA + 1, false);
    for (int a : arr) {
        if (!exist[a]) {
            exist[a] = true;
            nums.push_back(a);
        }
    }

    vector<bool> vis(maxA + 1, false);
    queue<int> q;

    // 初始状态：x 对各参数取模的结果
    for (int a : nums) {
        if (a <= x) {
            int r = x % a;
            if (!vis[r]) {
                vis[r] = true;
                q.push(r);
            }
        }
    }

    // BFS
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        for (int a : nums) {
            if (a <= v) {
                int nv = v % a;
                if (!vis[nv]) {
                    vis[nv] = true;
                    q.push(nv);
                }
            }
        }
    }

    // 小于 mn 的最大可达值
    int ans = 0;
    for (int i = 0; i < mn; i++) {
        if (vis[i]) {
            ans = i;
        }
    }
    return ans;
}

